import * as T from 'three';import {createGPURenderer} from '../gpu-particles.js';import {componentDefaults} from '../scene-components.js';import {createGameCamera,selectGameCamera} from '../game-camera.js';import {CameraViewRendering} from '../camera-view-rendering.js';
export async function cameraViewsGPU(){const canvas=document.createElement('canvas');document.body.append(canvas);const renderer=await createGPURenderer(canvas);renderer.setSize(160,100);const scene=new T.Scene(),objects=[],groups=new Map(),views=new CameraViewRendering(r=>r.hbBloom());scene.background=new T.Color('black');let checks=0;try{for(const [id,x,color]of [['A',-4,'#ff0000'],['B',4,'#00ff00']]){const p={...componentDefaults('Camera'),main:id==='A',projection:'orthographic',orthographicSize:1,screenOutput:true,screenRegion:id==='A'?'left':'right'},g=new T.Group(),c=createGameCamera(p);c.position.z=5;g.position.x=x;g.add(c);g.userData.gameCamera=c;scene.add(g);groups.set(id,g);objects.push({id,visible:true,components:[{id:'camera',type:'Camera',properties:p}]});const mesh=new T.Mesh(new T.PlaneGeometry(4,3),new T.MeshBasicMaterial({color,toneMapped:false}));mesh.position.x=x;scene.add(mesh);}const camera=selectGameCamera(objects,{width:160,height:100},null,id=>groups.get(id));views.render(renderer,scene,camera,objects,()=>{},()=>{});const device=renderer.backend.device,texture=renderer.backend.context.getCurrentTexture(),buffer=device.createBuffer({size:768*100,usage:GPUBufferUsage.COPY_DST|GPUBufferUsage.MAP_READ}),encoder=device.createCommandEncoder();encoder.copyTextureToBuffer({texture},{buffer,bytesPerRow:768},{width:160,height:100});device.queue.submit([encoder.finish()]);await buffer.mapAsync(GPUMapMode.READ);const pixels=new Uint8Array(buffer.getMappedRange().slice(0));buffer.unmap();buffer.destroy();for(const [x,color]of [[40,[255,0,0]],[120,[0,255,0]]]){const at=50*768+x*4,pixel=[...pixels.slice(at,at+4)];if(texture.format.startsWith('bgra'))[pixel[0],pixel[2]]=[pixel[2],pixel[0]];if(!pixel.slice(0,3).every((v,i)=>Math.abs(v-color[i])<6))throw Error(JSON.stringify({x,pixel,color}));checks++;}if(renderer.hbGPUErrors.length)throw Error(renderer.hbGPUErrors.join(';'));return {passed:true,checks,backend:'WebGPU',split:true,sharedDevice:true,validationErrors:0};}finally{views.dispose();scene.traverse(n=>{n.geometry?.dispose();n.material?.dispose();});renderer.dispose();canvas.remove();}}
